import UIKit

struct GlassEffectFactory {
    @MainActor
    static func makeBlurView(style: UIBlurEffect.Style) -> UIVisualEffectView {
        let blur = UIBlurEffect(style: style)
        let view = UIVisualEffectView(effect: blur)
        view.clipsToBounds = true
        return view
    }
}

let glassView = GlassEffectFactory.makeBlurView(style: .systemMaterial)
print("Glass view created: \(glassView.clipsToBounds)")

import UIKit

class VibrantContainerFactory {
    @MainActor
    static func makeVibrantContainer(blurEffect: UIBlurEffect) -> UIVisualEffectView {
        let vibrancy = UIVibrancyEffect(blurEffect: blurEffect, style: .label)
        return UIVisualEffectView(effect: vibrancy)
    }
}

let testBlur = UIBlurEffect(style: .systemMaterial)
let vibrantView = VibrantContainerFactory.makeVibrantContainer(blurEffect: testBlur)
print("Vibrant created: \(vibrantView.effect != nil)")

import UIKit

struct AccessibilityColorResolver {
    static func resolveBackgroundColor(reduceTransparency: Bool) -> UIColor {
        return reduceTransparency ? UIColor.systemBackground : UIColor.clear
    }
}

let resolved = AccessibilityColorResolver.resolveBackgroundColor(reduceTransparency: true)
print("Resolved opaque: \(resolved == UIColor.systemBackground)")
